#include <algorithm>
#include <iostream>
#include <vector>

int main()
{
    std::vector<int> pages{9, 2, 6, 4};
    std::sort(pages.begin(), pages.end());
    for (int value : pages) std::cout << value << '\n';
    const auto found = std::find(pages.begin(), pages.end(), 6);
    if (found != pages.end()) std::cout << "Found: " << *found << '\n';
    const auto even = std::count_if(pages.begin(), pages.end(),
                                   [](int value) { return value % 2 == 0; });
    std::cout << "Even: " << even << '\n';
}
